                                          "question": "Who can participate in the NTI Class 8 English Olympiad?",
                                          "answer": "The NTI Class 8 English Olympiad is open to all students currently enrolled in Grade 8 across various recognized educational boards (CBSE, ICSE, State Boards, etc.). There are no minimum marks required in regular school exams to be eligible for this Olympiad."
