                        "frequently-asked-questions": {
                              "heading": "Frequently Asked Questions",
                              "type": "faq",
                              "content": [
                                    {
                                          "question": "Who can participate in the NTI Class 6 Finance Olympiad?",
                                          "answer": "The NTI Class 6 Finance Olympiad is open to all students currently enrolled in Grade 6 across various recognized educational boards (CBSE, ICSE, State Boards, etc.). There are no minimum marks required in regular school exams to be eligible for this Olympiad."
                                    },
                                    {
                                          "question": "Is there any negative marking?",
                                          "answer": "No, there is absolutely no negative marking in the NTI Class 6 Finance Olympiad. Students are encouraged to attempt all questions without the fear of losing marks for incorrect answers."
                                    },
                                    {
                                          "question": "Can students register individually?",
                                          "answer": "Yes, students have the flexibility to register individually for the examination. While we highly encourage schools to participate and register their students in bulk, parents or guardians can directly enroll their children if their respective schools are not participating."
                                    },
                                    {
                                          "question": "What is the medium of the examination?",
                                          "answer": "The NTI Class 6 Finance Olympiad is conducted entirely in the English language. All question papers, instructions, and communication related to the examination will be provided in English."
                                    }
                              ]
                        }
